# Let's try a lazy SAT approach: solve without 5-cycle constraints first, then add as needed.

from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
import itertools

n = 27
min_deg = 3
max_deg = 5

# Variables
edges = {}
var_idx = 0
for i in range(n):
    for j in range(i+1, n):
        var_idx += 1
        edges[(i,j)] = var_idx

num_vars = var_idx
print(f"Edge variables: {num_vars}")

def build_solver():
    s = Glucose3()
    # Degree constraints
    vertex_pairs = {i: [] for i in range(n)}
    for (u,v), var in edges.items():
        vertex_pairs[u].append(var)
        vertex_pairs[v].append(var)

    nv = num_vars
    for v in range(n):
        lits = vertex_pairs[v]
        if len(lits) > max_deg:
            c = CardEnc.atmost(lits=lits, bound=max_deg, encoding=EncType.seqcounter, top_id=nv)
            for cl in c.clauses:
                s.add_clause(cl)
            nv += c.nv
        if min_deg > 0:
            c = CardEnc.atleast(lits=lits, bound=min_deg, encoding=EncType.seqcounter, top_id=nv)
            for cl in c.clauses:
                s.add_clause(cl)
            nv += c.nv
    return s, nv

def add_triangle_constraints(s):
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                s.add_clause([-edges[(i,j)], -edges[(i,k)], -edges[(j,k)]])

def add_4cycle_constraints(s):
    for combo in itertools.combinations(range(n), 4):
        a,b,c,d = combo
        s.add_clause([-edges[tuple(sorted((a,b)))], -edges[tuple(sorted((b,c)))], -edges[tuple(sorted((c,d)))], -edges[tuple(sorted((d,a)))]])
        s.add_clause([-edges[tuple(sorted((a,b)))], -edges[tuple(sorted((b,d)))], -edges[tuple(sorted((d,c)))], -edges[tuple(sorted((c,a)))]])
        s.add_clause([-edges[tuple(sorted((a,c)))], -edges[tuple(sorted((c,b)))], -edges[tuple(sorted((b,d)))], -edges[tuple(sorted((d,a)))]])

def decode_solution(model):
