# Simpler: brute-force check for cycles of length 3,4,5
def find_cycle_of_length(edge_set, length):
    adj = {i: set() for i in range(n)}
    for u,v in edge_set:
        adj[u].add(v)
        adj[v].add(u)

    # For length 3,4,5 use combinatorial search
    if length == 3:
        for i in range(n):
            for j in adj[i]:
                if j > i:
                    for k in adj[i] & adj[j]:
                        if k > j:
                            return (i,j,k)
    elif length == 4:
        # Check all quadruples
        for a in range(n):
            for b in adj[a]:
                if b > a:
                    for c in adj[b]:
                        if c != a:
                            for d in adj[c]:
                                if d != b and d != a and a in adj[d]:
                                    return (a,b,c,d)
    elif length == 5:
        # Check all quintuples via BFS
        for a in range(n):
            for b in adj[a]:
                if b > a:
                    for c in adj[b]:
                        if c != a and c != b:
                            for d in adj[c]:
                                if d != a and d != b and d != c:
                                    for e in adj[d]:
                                        if e != a and e != b and e != c and e != d and a in adj[e]:
                                            return (a,b,c,d,e)
    return None

