# Build PG(2,3) graph
def make_canonical(v):
    x,y,z = v
    if x != 0:
        inv = 1 if x == 1 else 2
        return (1, (y*inv)%3, (z*inv)%3)
    elif y != 0:
        inv = 1 if y == 1 else 2
        return (0, 1, (z*inv)%3)
    else:
        return (0, 0, 1)

