import itertools

def find_clique_in_distance_graph(vertices, min_dist, target_size):
    """Find a set of vertices pairwise at distance >= min_dist"""
    n = len(vertices)
    # precompute compatibility
    compat = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if dist[vertices[i]][vertices[j]] >= min_dist:
                compat[i][j] = compat[j][i] = True

    # Search
    best = []
    def backtrack(candidates, current):
        nonlocal best
        if len(current) > len(best):
            best = current[:]
            print(f"Found set of size {len(best)}: {[vertices[i] for i in best]}")
        if len(current) == target_size:
            return True
        for idx, c in enumerate(candidates):
            # Check compatibility with all in current
            if all(compat[c][x] for x in current):
                new_cand = [x for x in candidates[idx+1:] if compat[c][x]]
                if backtrack(new_cand, current + [c]):
                    return True
        return False

    backtrack(list(range(n)), [])
    return [vertices[i] for i in best]

